from flask import render_template, url_for, flash, redirect, request
from app import app, db, bcrypt
from app.forms import RegistrationForm, LoginForm, ContributionForm, GroupForm
from app.models import User, Contribution, Group
from flask_login import login_user, current_user, logout_user, login_required

@app.route('/')
@app.route('/home.html')
def home():
    return render_template('home.html')


@app.route('/register.html', methods=['GET', 'POST'])
def register():
    form = RegistrationForm()
    if form.validate_on_submit():
        hashed_password = bcrypt.generate_password_hash(form.password.data).decode('utf-8')
        user = User(username=form.username.data, email=form.email.data, password=hashed_password)
        db.session.add(user)
        db.session.commit()
        flash('Your account has been created! You are now able to log in', 'success')
        return redirect(url_for('login'))
    return render_template('register.html', title='Register', form=form)

@app.route("/terms")
def terms():
    return render_template('terms.html', title='Terms and Conditions')

@app.route('/login.html', methods=['GET', 'POST'])
def login():
    if current_user.is_authenticated:
        return redirect(url_for('account'))
    form = LoginForm()
    if form.validate_on_submit():
        user = User.query.filter_by(email=form.email.data).first()
        if user and bcrypt.check_password_hash(user.password, form.password.data):
            login_user(user, remember=form.remember.data)
            return redirect(url_for('account'))
        else:
            flash ('Login Unsuccessful. Please check email and password', 'danger')
    return render_template('login.html', title='Login', form=form)

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('login'))

@app.route('/account.html')
@login_required
def account():
    user_contributions = Contribution.query.filter_by(user_id=current_user.id).all()
    total_user_contributions = sum(contribution.amount for contribution in user_contributions)
    all_groups = Group.query.all()
    
    return render_template('AfterLogin.html', title='Account', user=current_user,
         total_user_contributions=total_user_contributions, all_groups=all_groups)

@app.route("/account/create_group.html", methods=['GET', 'POST'])
@login_required
def create_group():
    form = GroupForm()
    if form.validate_on_submit():
         group = Group(
            name=form.name.data,
            description=form.description.data,
            contribution_amount=form.contribution_amount.data,
            start_date=form.start_date.data,
            end_date=form.end_date.data)
         db.session.add(group)
         db.session.commit()
        # Add the creator to the group members
         group.members.append(current_user)
         db.session.commit()
         flash(f'Group "{form.name.data}" has been created successfully!', 'success')
         return redirect(url_for('account'))
    
    return render_template('create_group.html', title='Create Group', form=form)

@app.route("/join_group/<int:group_id>", methods=['POST'])
@login_required
def join_group(group_id):
    group = Group.query.get_or_404(group_id)
    if group not in current_user.groups:
        current_user.groups.append(group)
        db.session.commit()
        flash(f'You have successfully joined the group "{group.name}"!', 'success')
    else:
        flash(f'You are already a member of the group "{group.name}".', 'info')
    return redirect(url_for('account'))

@app.route("/account/contribute.html", methods=['GET', 'POST'])
@login_required
def contribute():
    form = ContributionForm()
    
    # Populate group choices with groups the user is a member of
    form.group.choices = [(group.id, group.name) for group in current_user.groups]
    
    if form.validate_on_submit():
        contribution = Contribution(
            amount=form.amount.data,
            date_posted=form.date_posted.data,
            user_id=current_user.id,
            group_id=form.group.data)
        db.session.add(contribution)
        db.session.commit()
        flash(f'You have successfully made a contribution of ${form.amount.data:.2f}!', 'success')
        return redirect(url_for('account'))
    
    return render_template('contribute.html', title='Make a Contribution', form=form)

@app.route('/profile', methods=['GET', 'POST'])
@login_required
def update_profile():
    if request.method == 'POST':
        current_user.username = request.form['username']
        current_user.email = request.form['email']
        current_user.phone = request.form.get('phone', '')

        db.session.commit()
        flash("Profile updated successfully", "success")
        return redirect(url_for('update_profile'))
    
    return render_template('profile.html')

@app.route('/my_groups')
@login_required
def my_groups():
    return render_template('AfterLogin.html', user=current_user)

@app.route('/transactions')
@login_required
def transaction_history():
    transactions = Contribution.query.filter_by(user_id=current_user.id).order_by(Contribution.date_posted.desc()).all()
    return render_template('transaction.html', transactions=transactions)